def normalize_asyncpg_database_url(database_url: str) -> str:
    """Remove Prisma-only query params before passing DATABASE_URL to asyncpg."""
    parsed = urlsplit(database_url)
    query = urlencode(
        [
            (key, value)
            for key, value in parse_qsl(parsed.query, keep_blank_values=True)
            if key != "schema"
        ],
    )
    return urlunsplit(
        (
            parsed.scheme,
            parsed.netloc,
            parsed.path,
            query,
            parsed.fragment,
        ),
    )

def compact_text(value: object, limit: int = 1200) -> str | None:
    text = read_string(value)

    if text is None:
        return None

    normalized = " ".join(text.split())
    return normalized[:limit]

